fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = std::cmp::max(m, n);
    
    // Broadcast array a
    let a_broadcast = if m == 1 {
        // Repeat the single element max_len times
        vec![a[0]; max_len]
    } else {
        // m must equal max_len due to compatibility rules
        a
    };
    
    // Broadcast array b
    let b_broadcast = if n == 1 {
        // Repeat the single element max_len times
        vec![b[0]; max_len]
    } else {
        // n must equal max_len due to compatibility rules
        b
    };
    
    (a_broadcast, b_broadcast)
}